function routePrimitive(need) {
  if (need.humanInitiates && need.pattern) return 'prompt:' + need.name;
  if (need.stable && need.addressable) return 'resource:' + need.name;
  if (need.computed || need.live || need.acts) return 'tool:' + need.name;
  return 'prompt:clarify-need';
}
const cases = [
  [{ humanInitiates: true, pattern: true, name: 'triage-ticket' }, 'prompt:triage-ticket'],
  [{ stable: true, addressable: true, name: 'policy' }, 'resource:policy'],
  [{ live: true, name: 'lookup-order' }, 'tool:lookup-order'],
  [{ acts: true, name: 'issue-refund' }, 'tool:issue-refund'],
  [{ vague: true }, 'prompt:clarify-need'],
];
let pass = 0;
for (const [need, expected] of cases) {
  const got = routePrimitive(need);
  if (got === expected) pass++;
  else console.log('MISS ' + JSON.stringify(need) + ' -> ' + got);
}
console.log(pass + '/' + cases.length + ' primitives routed');

